// Re-emit a single search item, decoupled from the rows returned by the
// existing-leads read, so the ScraperAPI nodes run exactly once no matter
// how many leads are already stored in the sheet.

const cfg = $('Configure').first().json;

return [{
  json: {
    query: cfg.query,
    countryCode: cfg.countryCode,
  },
  pairedItem: { item: 0 },
}];

// The Google Maps structured endpoint returns a metadata document, not the
// businesses: the actual results live behind `next_page_url`, a ready-made
// ScraperAPI request wrapping the Google Maps results page. Pull out the
// inner Google URL so the next node can fetch and autoparse it.

const getBody = (item) => {
  const resp = item && item.json && item.json.response;
  if (!resp || resp.body === undefined) return {};
  if (typeof resp.body === 'string') {
    try { return JSON.parse(resp.body); } catch (e) { return {}; }
  }
  return resp.body;
};

const meta = getBody($input.first());
const nextPage = meta.next_page_url || meta.nextPageURL || '';

// Pull the `url` query param out by hand — the n8n Code sandbox does not
// reliably expose the URL constructor. The inner Google URL is percent-
// encoded, so it never contains a literal `&` to break the match.
const match = /[?&]url=([^&]+)/.exec(nextPage);
let targetUrl = '';
if (match) {
  try { targetUrl = decodeURIComponent(match[1]); } catch (e) { targetUrl = match[1]; }
}

return [{ json: { targetUrl }, pairedItem: { item: 0 } }];

// Parse the autoparsed Google Maps results and flatten each business into a
// clean lead row. Applies the configured minimum-rating filter (on stars).
// Result fields: name, address (array), address_line, stars, ratings, type
// (array), url (website), phone_number, latitude, longitude, district.

const cfg = $('Configure').first().json;
const minRating = Number(cfg.minRating) || 0;

const getBody = (item) => {
  const resp = item && item.json && item.json.response;
  if (!resp || resp.body === undefined) return {};
  if (typeof resp.body === 'string') {
    try { return JSON.parse(resp.body); } catch (e) { return {}; }
  }
  return resp.body;
};

const numOrNull = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const s = typeof v === 'string' ? v.replace(/[^0-9.]/g, '') : v;
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : null;
};

const joinList = (v) => (Array.isArray(v) ? v.filter(Boolean).join(', ') : (v || ''));

const scrapedAt = new Date().toISOString();
const out = [];

$input.all().forEach((item, i) => {
  const body = getBody(item);
  const results = body.results || body.local_results || [];
  if (!Array.isArray(results)) return;

  for (const b of results) {
    const rating = numOrNull(b.stars ?? b.rating);
    if (minRating > 0 && (rating === null || rating < minRating)) continue;

    const name = b.name || b.title || '';
    const address = joinList(b.address) || b.address_line || '';
    const mapQuery = `${name} ${address}`.trim();

    out.push({
      json: {
        name,
        category: joinList(b.type),
        address,
        phone: b.phone_number || b.phone || '',
        website: b.url || b.website || '',
        rating,
        reviews: numOrNull(b.ratings ?? b.reviews),
        district: b.district || '',
        latitude: b.latitude ?? null,
        longitude: b.longitude ?? null,
        google_maps_url: mapQuery ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(mapQuery)}` : '',
        search_query: cfg.query,
        scraped_at: scrapedAt,
      },
      pairedItem: { item: i },
    });
  }
});

return out;

// Drop businesses already in the sheet (matched by name + address) and any
// duplicates within this batch, then cap to the configured maximum so a broad
// query can't flood the sheet.

const maxResults = Number($('Configure').first().json.maxResults) || 20;

const keyOf = (r) =>
  `${String(r.name || '').toLowerCase().trim()}|${String(r.address || '').toLowerCase().trim()}`;

const seen = new Set(
  $('Read Existing Leads').all()
    .map((r) => keyOf(r.json || {}))
    .filter((k) => k && k !== '|')
);

const out = [];
for (const item of $input.all()) {
  const lead = item.json;
  const key = keyOf(lead);
  if (!key || key === '|' || seen.has(key)) continue;
  seen.add(key);
  out.push({ json: lead, pairedItem: item.pairedItem });
  if (out.length >= maxResults) break;
}

return out;
